{
  "name": "Agilent E8357A 矢量网络分析仪",
  "name_en": "Agilent E8357A Vector Network Analyzer",
  "manufacturer": "Agilent Technologies",
  "description": "这是一台射频/微波矢量网络分析仪，用于扫频测量器件或网络的散射参数，如 S11、S21、S12 和 S22。实验中常用于表征滤波器、谐振器、传输线、电缆、放大器及其他高频器件的反射、传输与频率响应。",
  "description_en": "This is an RF/microwave vector network analyzer used to perform swept-frequency measurements of scattering parameters such as S11, S21, S12, and S22. In the lab it is commonly used to characterize the reflection, transmission, and frequency response of filters, resonators, transmission lines, cables, amplifiers, and other high-frequency components.",
  "actions": [
    {
      "action_name": "auto-trace",
      "description": "选择测量迹线或散射参数。",
      "description_en": "Select the measurement trace or S-parameter."
    },
    {
      "action_name": "auto-catalog",
      "description": "获取已配置测量通道与迹线目录。",
      "description_en": "Get the catalog of configured channels and traces."
    },
    {
      "action_name": "auto-readX",
      "description": "读取扫频横轴数据，如频率点。",
      "description_en": "Read the sweep x-axis data, such as frequency points."
    },
    {
      "action_name": "auto-readS",
      "description": "读取所选迹线的复数散射参数数据。",
      "description_en": "Read the complex S-parameter data for the selected trace."
    },
    {
      "action_name": "auto-points",
      "description": "获取/设置扫频点数。",
      "description_en": "Get/set the number of sweep points."
    },
    {
      "action_name": "auto-bandwidth",
      "description": "获取/设置中频带宽。",
      "description_en": "Get/set the IF bandwidth."
    },
    {
      "action_name": "auto-sourcepower",
      "description": "获取/设置源输出功率。",
      "description_en": "Get/set the source output power."
    },
    {
      "action_name": "auto-start",
      "description": "获取/设置扫频起始频率。",
      "description_en": "Get/set the sweep start frequency."
    },
    {
      "action_name": "auto-stop",
      "description": "获取/设置扫频终止频率。",
      "description_en": "Get/set the sweep stop frequency."
    },
    {
      "action_name": "auto-reference",
      "description": "获取参考时钟源状态。",
      "description_en": "Get the reference clock source status."
    },
    {
      "action_name": "auto-screenshot",
      "description": "采集仪器屏幕截图。",
      "description_en": "Capture a screenshot of the instrument display."
    }
  ],
  "tag_hints": [
    "vector network analyzer",
    "S-parameter measurement",
    "RF characterization",
    "microwave measurement",
    "frequency sweep",
    "reflection and transmission",
    "IF bandwidth",
    "source power control"
  ]
}

